NAME = 'HunKar: Revideált Károli Biblia 1908'
BOOK = 'Ruth'

CHAPTERS = {
    1: {
        1: 'És lőn azon napokban, a mikor a bírák bíráskodának, éhség lőn a földön. És elméne egy férfi a Júda Bethleheméből, hogy Moáb mezején tartózkodjék; ő meg a felesége, és a két fia.',
        2: 'A férfi neve Elimélek és felesége neve Naómi; két fiok neve pedig Mahlon és Kiljon; efrataiak, a Júda Bethleheméből valók. És eljutának Moáb mezejére, és ott valának.',
        3: 'Meghala pedig Elimélek a Naómi férje, és marada ő és az ő két fia.',
        4: 'A kik Moábita leányokat vőnek feleségül; az egyiknek neve Orpa, és a másiknak neve Ruth. És ott lakozának közel tíz esztendeig.',
        5: 'Meghalának ők is mind a ketten, Mahlon is, Kiljon is, és marada az asszony az ő két fia és férje nélkül.',
        6: 'Felkele azért ő és az ő menyei, és ő visszatére Moáb mezejéről; mert hallotta vala Moáb mezején, hogy meglátogatta az Úr az ő népét, hogy adjon nékik kenyeret.',
        7: 'És kiméne arról a helyről, a hol volt, és vele a két menye. És menének az úton, hogy visszatérjenek Júda földére,',
        8: 'És monda Naómi az ő két menyének: Menjetek, térjetek vissza, kiki az ő anyjának házához. Cselekedjék az Úr irgalmasságot veletek, a miképen ti cselekedtetek a megholtakkal és én velem!',
        9: 'Adja az Úr tinéktek, hogy találjatok nyugodalmat, kiki az ő férje házában. És megcsókolá őket; és ők nagy felszóval sírának.',
        10: 'És mondák néki: Bizony mi veled együtt térünk a te népedhez!',
        11: 'Naómi pedig mondá: Térjetek vissza leányaim! Miért jönnétek én velem? Hát ugyan vannak-é még fiak az én méhemben, a kik férjeitek lehetnének?',
        12: 'Térjetek vissza leányaim! menjetek, mert én már vénebb vagyok, semhogy férjhez mehetnék. Még ha azt mondanám is, hogy van reménységem; még ha ez éjjel férjhez mennék is és szülnék is fiakat:',
        13: 'Ugyan megvárhatnátok-é őket, a míg felnőnek? Ugyan megtartóztatnátok-é magatokat miattok, hogy férjhez ne menjetek? Ne, édes leányaim! Mert nagyobb az én keserüségem, mint a tietek, mert engem talált az Úrnak keze.',
        14: 'Azok pedig nagy felszóval tovább sírának. És Orpa megcsókolá az ő napát; Ruth azonban ragaszkodék hozzá.',
        15: 'Ő pedig monda: Ímé a te sógorasszonyod visszatért az ő népéhez, és az ő isteneihez, térj vissza te is a te sógorasszonyod után.',
        16: 'Ruth pedig monda: Ne unszolj, hogy elhagyjalak, hogy visszaforduljak tőled. Mert a hova te mégy, oda megyek, és a hol te megszállsz, ott szállok meg; néped az én népem, és Istened az én Istenem.',
        17: 'A hol te meghalsz, ott halok meg, ott temessenek el engem is. Úgy tegyen velem az Úr akármit, hogy csak a halál választ el engem tőled.',
        18: 'Mikor pedig látá, hogy erősködik vele menni, nem szóla néki többet.',
        19: 'És menének mind a ketten, míglen Bethlehembe érkezének. És lőn, hogy mikor Bethlehembe érkezének, megmozdult az egész város miattok, és mondák: Nemde nem Naómi ez?',
        20: 'És ő monda nékik: Ne hívjatok engem Naóminak, hívjatok inkább Márának, mert nagy keserűséggel illetett engem a Mindenható.',
        21: 'Többed magammal mentem el, és elárvultan hozott vissza engemet az Úr; miért hívnátok hát engem Naóminak, holott az Úr ellenem fordult, és a Mindenható nyomorúsággal illetett engemet?',
        22: 'Így tért vissza Naómi, és vele a Moábita Ruth, az ő menye, a ki hazatért Moáb mezejéről. Megérkezének pedig Bethlehembe az árpaaratás kezdetén.',
    },
    2: {
        1: 'Vala pedig Naóminak egy rokona az ő férje után, előkelő derék ember Elimélek nemzetségéből; neve Boáz.',
        2: 'És monda a Moábita Ruth Naóminak: Hadd menjek, kérlek, a mezőre, hogy kalászokat szedegessek az után, a kinek szemei előtt kedvességet találok. És az monda: Menj édes leányom.',
        3: 'Elméne azért és odaérkezék, szedegete a mezőn az aratók után, és történetesen oda talált a Boáz szántóföldjére, a ki Elimélek nemzetségéből való volt.',
        4: 'És ímé Boáz kijöve Bethlehemből, és monda az aratóknak: Az Úr legyen veletek! És ők mondának néki: Áldjon meg téged az Úr!',
        5: 'És monda Boáz az ő szolgájának, a ki az aratók felügyelője volt: Kié ez a leányzó?',
        6: 'És felele a szolga, az aratók felügyelője, és monda: Az a Moábita leányzó ez, a ki Naómival jött a Moáb mezejéről.',
        7: 'A ki mondá: Hadd szedegessek, kérlek, és hadd tarlózgassak a kévék közt az aratók után. És ide jöve, és itt marada reggeltől fogva mind mostanig: és csak épen most pihent egy keveset a házban.',
        8: 'És mondá Boáz Ruthnak: Ugyan hallod-é édes leányom! Ne menj szedegetni más mezőre és el ne menj innen; hanem menj mindenütt szolgálóim után.',
        9: 'Szemeid legyenek a mezőn, a melyet aratnak, és járj utánok. Ímé meghagytam a szolgáknak, hogy ne bántsanak téged, és ha megszomjúhozol, menj az edényekhez és igyál abból, a mit a szolgák merítenek.',
        10: 'Akkor ez arczra borula és meghajtá magát a földig, és monda néki: Hogy-hogy találtam ilyen kedvességet a te szemeid előtt, hogy rám tekintettél, holott én idegen vagyok?',
        11: 'Boáz pedig felele, és monda néki: Bizony elmondtak nékem mindent, amit cselekedtél a te napaddal, férjed halála után, hogy elhagytad a te atyádat és a te anyádat és a te születésednek földét, és jöttél ahhoz a néphez, a melyet nem ismertél azelőtt.',
        12: 'Fizessen meg az Úr a te cselekedetedért, és legyen teljes a te jutalmad az Úrtól, Izráelnek Istenétől, a kinek szárnyai alatt oltalmat keresni jöttél.',
        13: 'Ez pedig monda: Találjak kedvességet a te szemeid előtt uram, mert megvigasztaltál engem, és mert a te szolgálódnak szívéhez szóltál, holott én nem vagyok a te szolgálóleányaid közül.',
        14: 'És az evésnek idejekor szóla néki Boáz: Jer ide, és egyél a kenyérből, és mártsd be a te falatodat az eczetes lébe. És ő leüle az aratók mellé. És pergelt gabonát nyújtott néki, és evett, s jóllakott, sőt még hagyott is.',
        15: 'Azután felállott, hogy szedegessen és Boáz megparancsolta az ő szolgáinak, mondván: A kévék között is hadd szedegessen, és meg ne pirongassátok őt.',
        16: 'Sőt húzogassatok ki néki a kévékből is, és hagyogassatok el, hogy szedje fel, és meg ne dorgáljátok őt.',
        17: 'És ő szedegete a mezőn mind estiglen, és kicsépelé, a mit szedegetett, és lett abból szinte egy efa árpa.',
        18: 'És felvevé és beméne a városba, és napaasszonya látá, a mit ő szedegetett. Aztán elővevé és odaadá néki, a mit meghagyott, minekutána jóllakott vala.',
        19: 'És monda néki az ő napaasszonya: Hol szedegettél ma, és hol munkálkodtál? Áldott legyen, a ki rád tekintett. És elbeszélte az ő napaasszonyának, hogy kinél munkálkodott, és monda: Annak a férfiúnak a neve, a kinél ma munkálkodtam: Boáz.',
        20: 'És monda Naómi az ő menyének: Áldott legyen ő az Úrtól, a ki nem vonta meg irgalmasságát az élőktől és a megholtaktól! És Naómi monda néki: Közel valónk nékünk az a férfiú; legközelebbi rokonaink közül való ő.',
        21: 'És szóla a Moábita Ruth: Még azt is mondta ő nékem: Menj mindenütt az én munkásaim után, a míg csak el nem végzik az én egész aratásomat.',
        22: 'És monda Naómi Ruthnak, az ő menyének: Jó, édes leányom, hogy az ő szolgálóival jársz, ne is találjanak téged más mezőn.',
        23: 'Így járt ő mindenütt a Boáz szolgálói után, szedegetve, míg az árpaaratás és búzaaratás bevégződött; és az ő napaasszonyával lakott.',
    },
    3: {
        1: 'És monda néki Naómi, az ő napaasszonya: Édes leányom! ne keressek-é néked nyugalmat, hogy jól legyen dolgod?',
        2: 'Avagy nem rokonunk-é Boáz, a kinek szolgálóival voltál? Ímé ő az éjjel árpát szór a szérűn.',
        3: 'Annakokáért fürödjél meg, és kend meg magadat, és vedd magadra ruháidat, és menj le a szérűre; észre ne vétesd magadat a férfiúval, a míg el nem végezi ételét és italát.',
        4: 'És majd ha lefekszik, jegyezd meg a helyet, a hol fekszik, és menj oda, és hajtsd fel a leplet lábánál, és feküdjél oda. Ő majd megmondja néked, mit cselekedjél.',
        5: 'És ő monda néki: Mindazt, a mit mondasz, megcselekszem.',
        6: 'És lement a szérűre, és mindent úgy cselekedett, a mint napaasszonya parancsolta.',
        7: 'És Boáz evett és ivott, és felvidámult az ő szíve. És elment, hogy lefeküdjék a garmada szélén; és az eljött titkon, és felhajtá lába felől a leplet, és lefeküvék.',
        8: 'Történt pedig éjfél tájon, hogy felrettent a férfiú, és odafordult. És ímé: asszony fekszik az ő lábainál.',
        9: 'És monda: Kicsoda vagy te? És az monda: Én Ruth vagyok, a te szolgálód; terjeszszed ki hát takaródat a te szolgálódra, mert te vagy a legközelebbi rokon.',
        10: 'És ő monda: Az Úrnak áldotta vagy te, édes leányom! Utóbbi szereteteddel jobbat cselekedtél, mint az elsővel: hogy nem jártál az ifjak után, sem szegény, sem gazdag után.',
        11: 'Most hát, édes leányom, ne félj! Mindent, a mit mondasz, megteszek néked; mert tudja az én népemnek egész kapuja, hogy derék asszony vagy.',
        12: 'És most: bizony igaz, hogy közel rokon vagyok: de van nálamnál még közelebbi rokon is.',
        13: 'Ez éjszakán hálj itt; s majd reggel, ha az megvált téged, jó: váltson meg; ha pedig nem akar téged megváltani, akkor én váltalak meg. Él az Úr! Feküdj itt reggelig.',
        14: 'És feküvék az ő lábainál reggelig, és felkele, mielőtt valaki az ő felebarátját megismerheté, mert mondá: Meg ne tudja senki, hogy ez az asszony a szérűre jött.',
        15: 'És monda: Add ide a nagy kendődet, a mely rajtad van, és tartsd. És ő oda tartotta azt. Boáz pedig mért hat mérték árpát, és feladta néki, maga pedig bement a városba.',
        16: 'És elméne az ő napaasszonyához, és az monda: Hogy vagy édes leányom? És ő elbeszélt néki mindent, a mit cselekedett vele az a férfi.',
        17: 'És monda: Ezt a hat mérték árpát adá nékem, mert monda: Ne menj üresen a te napadhoz.',
        18: 'És monda Naómi: Légy veszteg leányom, míg megtudod, hova dől el a dolog; mert nem nyugszik az a férfiú, míg véghez nem viszi a dolgot még ma.',
    },
    4: {
        1: 'Boáz pedig felment a kapuba, és ott leült. És ímé arra ment az a legközelebbi rokon, a kiről Boáz beszélt vala, és monda néki: Jer csak, ülj ide atyafi. És az oda ment és leüle.',
        2: 'Ekkor ő maga mellé vett tíz férfiút a város vénei közül és monda: Üljetek ide! És azok leülének.',
        3: 'És ő monda a legközelebbi rokonnak: Azt a darab szántóföldet, mely a mi atyánkfiáé, Eliméleké volt, eladja Naómi, a ki haza jött a Moáb mezejéről.',
        4: 'Én pedig gondoltam, hogy füledbe juttatom, mondván: Vedd meg az itt ülők előtt és az én népemnek vénei előtt. Ha megváltod: váltsd meg; és ha nem váltod meg: jelentsd ki előttem, hogy tudjam; mert rajtad kívül nincs, a ki megváltaná, és én vagyok utánad. És az monda: Én megváltom.',
        5: 'És monda Boáz: A mely napon megveszed a szántóföldet Naómi kezéből, akkor a Moábita Ruthtól, a megholtnak feleségétől veszed meg, hogy nevet támaszsz a megholtnak, az ő örökségében.',
        6: 'A legközelebbi rokon pedig monda: Nem válthatom meg magamnak, hogy el ne veszessem a magam örökségét; váltsd meg te magadnak az én rokoni részemet, mert én nem válthatom meg.',
        7: 'Ez vala pedig a szokás régen Izráelben, a megváltás és cserélés alkalmával, minden dolognak megerősítésére: A férfi lehúzta az ő saruját és oda adta felebarátjának, és ez volt a bizonyság Izráelben.',
        8: 'Monda annakokáért a legközelebbi rokon Boáznak: Vedd meg magadnak! És lehúzta a saruját.',
        9: 'És monda Boáz a véneknek és az egész népnek: Ti vagytok tanui ma, hogy megvettem mindent, a mi Eliméleké volt, és mindent, a mi Kiljoné és Mahloné volt, Naómi kezéből;',
        10: 'Sőt a Moábita Ruthot is, Mahlonnak feleségét feleségül vettem, hogy nevet támaszszak a megholtnak az ő örökségében, és ki ne veszszen a megholtnak neve az ő atyjafiai közül és az ő helységének kapujából. Tanuk vagytok ma.',
        11: 'És monda az egész nép, mely a kapuban vala és a vének: Tanuk vagyunk! Tegye az Úr az asszonyt, a ki a te házadba megy, olyanná, mint Rákhel és Lea, a kik ketten építették fel Izráel házát, és gyűjts vagyont Efratában és szerezz nevet Bethlehemben.',
        12: 'És a te házad legyen, miként a Pérecz háza – a kit Thámár szült Júdának – abból a magzatból, a melyet az Úr adánd néked ettől az asszonytól.',
        13: 'Elvevé annakokáért Boáz Ruthot, és lőn az néki felesége, és beméne hozzá, és megadá az Úr, hogy az fogana az ő méhében, és szült fiút.',
        14: 'És mondák az asszonyok Naóminak: Áldott az Úr, a ki ma nem engedte meg, hogy rokon nélkül maradj; emlegessék az ő nevét Izráelben!',
        15: 'És legyen ő a te lelkednek megvidámítója, és vénségednek istápolója, mert menyed szülte őt, az, a ki téged szeret, és a ki többet ér néked hét fiúnál.',
        16: 'Ekkor megfogá Naómi a gyermeket, és ölébe vevé, és dajkája lőn annak.',
        17: 'A szomszédasszonyok pedig nevet adának néki, mondván: Fia született Naóminak, és nevezték az ő nevét Obednek. Ez az apja Isainak, a Dávid atyjának.',
        18: 'És a Pérecz nemzetségei ezek: Pérecz nemzé Hesront;',
        19: 'Hesron pedig nemzé Rámot, és Rám nemzé Amminádábot;',
        20: 'Amminádáb pedig nemzé Naássont, és Naásson nemzé Sálmónt;',
        21: 'Sálmón pedig nemzé Boázt, és Boáz nemzé Obedet;',
        22: 'És Obed nemzé Isait, Isai pedig nemzé Dávidot.',
    },
}
